package hu.bankmonitor.payments.accounts;

import com.tngtech.archunit.core.domain.JavaClasses;
import com.tngtech.archunit.core.importer.ClassFileImporter;
import com.tngtech.archunit.core.importer.ImportOption;
import com.tngtech.archunit.lang.ArchRule;
import hu.bankmonitor.testsupport.boundaryviolations.lockedpath.LockHolder;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static com.tngtech.archunit.core.domain.JavaClass.Predicates.resideInAnyPackage;
import static com.tngtech.archunit.lang.conditions.ArchConditions.transitivelyDependOnClassesThat;
import static com.tngtech.archunit.lang.syntax.ArchRuleDefinition.noClasses;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

/**
 * The constraint that makes pessimistic locking affordable: a transaction holding row
 * locks waits on nothing slower than the database.
 *
 * <p>Design decision 4 keeps the Exchange Rate call in a phase of its own precisely so
 * that it is not inside these locks, and design decision 6 says that placement is what
 * makes the whole locking design viable. The half of that which lives in
 * {@code transfers} — that the rate is fetched with no transaction open — is ticket 26's
 * to assert. What is assertable here is the other half: that the operation holding the
 * locks cannot reach anything but the database, however far down its call graph the reach
 * would be.
 *
 * <p>The rule is <em>transitive</em> for that reason. A direct-dependency rule would pass
 * a lock holder that delegates the HTTP call one class further down, which is the shape
 * the mistake actually takes. {@link LockHolder} is a fixture in exactly that shape, and
 * it is measured against because a transitive rule that had quietly stopped following
 * hops would look identical to a passing one.
 */
class LockedPathTouchesOnlyTheDatabaseTest {

	/**
	 * Sockets, files and every HTTP client the classpath offers, plus the {@code fx} slice
	 * itself: ticket 25 puts a real provider call behind it, and no amount of it belongs
	 * under a lock.
	 */
	private static final String[] IO_BEYOND_THE_DATABASE = {
			"java.net..",
			"java.nio.file..",
			"jakarta.servlet..",
			"org.springframework.web..",
			"org.springframework.http..",
			"hu.bankmonitor.payments.fx..",
			"hu.bankmonitor.payments.mockfx..",
	};

	@Test
	@DisplayName("the operation that holds the locks reaches nothing but the database")
	void theLockHolderReachesNothingButTheDatabase() {
		JavaClasses productionClasses = new ClassFileImporter()
				.withImportOption(ImportOption.Predefined.DO_NOT_INCLUDE_TESTS)
				.importPackages("hu.bankmonitor.payments");

		reachesNoIoBeyondTheDatabase(AccountLocking.class).check(productionClasses);
	}

	private static ArchRule reachesNoIoBeyondTheDatabase(Class<?> lockHolder) {
		return noClasses()
				.that().belongToAnyOf(lockHolder)
				.should(transitivelyDependOnClassesThat(resideInAnyPackage(IO_BEYOND_THE_DATABASE)))
				.because("a transaction holding account locks must never wait on a slow provider");
	}

	@Test
	@DisplayName("a lock holder that reaches an HTTP client one hop down is reported")
	void detectsIoOneHopBelowTheLockHolder() {
		JavaClasses violation = new ClassFileImporter()
				.importPackages("hu.bankmonitor.testsupport.boundaryviolations.lockedpath");

		assertThatThrownBy(() -> reachesNoIoBeyondTheDatabase(LockHolder.class).check(violation))
				.isInstanceOf(AssertionError.class)
				.hasMessageContaining("RateLookup")
				.hasMessageContaining("RestClient");
	}
}
